// Validate & normalize the run log row: enum checks + numeric coercion, so the live_source_runs tab
// stays queryable. Throws a clear error instead of writing junk. No external calls.
function str(v){return v==null?'':String(v).trim();}
function num(v){var n=Number(v);return isFinite(n)?n:0;}
const MODES=['fixture','live','deterministic','llm_summary','blocked_by_guard'];
const STATUSES=['completed','failed','blocked','partial'];
const FAMILIES=['classifieds','social_channel','public_discussion','public_lead_source','lead_triage','web_competitor','report_layer','other'];
const r=$input.first().json;
if(!str(r.run_id))throw new Error('WF15: run_id is required');
if(!str(r.workflow))throw new Error('WF15: workflow is required');
if(MODES.indexOf(str(r.mode))<0)throw new Error('WF15: mode must be one of '+MODES.join('/'));
if(STATUSES.indexOf(str(r.status))<0)throw new Error('WF15: status must be one of '+STATUSES.join('/'));
if(FAMILIES.indexOf(str(r.source_family))<0)throw new Error('WF15: source_family must be one of '+FAMILIES.join('/'));
if(['yes','no'].indexOf(str(r.approval_token_used))<0)throw new Error('WF15: approval_token_used must be yes/no — never the token itself');
if(/I_APPROVE/i.test(JSON.stringify(r)))throw new Error('WF15: approval token VALUE detected in the entry — remove it; log only yes/no');
const NUM=['max_items','items_received','items_relevant','items_written_raw','items_unique','items_duplicate','hard_skipped','external_calls','estimated_source_cost_usd','llm_calls','estimated_llm_cost_usd'];
const out=Object.assign({},r);
for(const k of NUM)out[k]=num(r[k]);
return [{ json: out }];

// Final summary. No external calls.
const r=$('Validate Run Log Row').first().json;
return [{ json: { workflow:'15 - Live Source Run Logger', logged_run_id:r.run_id, logged_workflow:r.workflow, mode:r.mode, status:r.status, estimated_source_cost_usd:r.estimated_source_cost_usd, estimated_llm_cost_usd:r.estimated_llm_cost_usd, next_action:'Row appended to live_source_runs. Keep COSTS_AND_LIMITS.md in sync for paid runs.' } }];
